public class TestClass {
    public void someMethod() {
        // Target for cleanup
        String s = new java.lang.StringBuffer("hello").toString();
        System.out.println(s);

        String literal = "world";
        // Another target for cleanup
        String s2 = new java.lang.StringBuffer(literal).toString();
        System.out.println(s2);
    }

    public void acceptString(String data) {
        System.out.println(data);
    }

    public void callAcceptString() {
        // Target for cleanup where implicit toString() or overload resolution applies
        acceptString(new java.lang.StringBuffer("data"));
    }
}

afterExample:
public class TestClass {
    public void someMethod() {
        // Cleaned up
        String s = "hello";
        System.out.println(s);

        String literal = "world";
        // Cleaned up
        String s2 = literal;
        System.out.println(s2);
    }

    public void acceptString(String data) {
        System.out.println(data);
    }

    public void callAcceptString() {
        // Cleaned up
        acceptString("data");
    }
}

negativeExample:
public class NegativeTestClass {
    public void someMethod() {
        StringBuilder sb = new StringBuilder("dynamic");
        // $arg is a StringBuilder, not a String; should not match.
        String s = new java.lang.StringBuffer(sb).toString();
        System.out.println(s);

        // Not a StringBuffer constructor, should not match.
        String s2 = "already a string";
        System.out.println(s2);
    }
}
